Problem:
In the North, a delivery service can deliver using either sleds or snowmobile. Snowmobiles can deliver 150 packages while sleds can deliver 125 packages. Most villages do not want snowmobiles to pollute their regions. Therefore, there must be at least two times more sleds than snowmobiles. If the delivery service wants to deliver 150000 packages, minimize the total number of deliveries.

Model and facts:
{
 "model": {
  "variables": [
   {
    "name": "sleds",
    "lower": 0.0,
    "upper": null,
    "integer": true
   },
   {
    "name": "snowmobiles",
    "lower": 0.0,
    "upper": null,
    "integer": true
   }
  ],
  "objective": {
   "sense": "min",
   "terms": [
    {
     "var": "sleds",
     "coef": 1.0
    },
    {
     "var": "snowmobiles",
     "coef": 1.0
    }
   ]
  },
  "constraints": [
   {
    "name": "package_target",
    "terms": [
     {
      "var": "sleds",
      "coef": 125.0
     },
     {
      "var": "snowmobiles",
      "coef": 150.0
     }
    ],
    "sense": "==",
    "rhs": 150000.0
   },
   {
    "name": "sleds_at_least_twice_snowmobiles",
    "terms": [
     {
      "var": "sleds",
      "coef": 1.0
     },
     {
      "var": "snowmobiles",
      "coef": -2.0
     }
    ],
    "sense": ">=",
    "rhs": 0.0
   }
  ]
 },
 "facts": {
  "objective": 1125.0,
  "values": {
   "sleds": 750.0,
   "snowmobiles": 375.0
  },
  "binding": [
   "package_target",
   "sleds_at_least_twice_snowmobiles"
  ],
  "slack": {
   "package_target": 0.0,
   "sleds_at_least_twice_snowmobiles": 0.0
  },
  "shadow_prices": null
 }
}
